prompt.text:
Repair the complete CommonJS source below and return a corrected complete source file exporting exactly `{ encodeTable }`. `encodeTable(rows)` serializes a rectangular array of rows as comma-separated text. The outer array may be empty, producing `''`; otherwise each row must be an array with the same length. Cells may be strings, finite numbers, booleans, or `null`; null becomes an empty field. Convert other valid values with `String`. A field containing a comma, double quote, carriage return, or newline must be surrounded by double quotes, and every double quote inside it must be doubled. Preserve row and column order, join fields with commas and rows with `\n`, and never mutate input. Reject malformed rows, non-rectangular data, unsupported cells, `NaN`, and infinities with `TypeError`.

Known-bad source:
'use strict';

function encodeTable(rows) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  if (rows.length === 0) return '';
  if (!rows.every(Array.isArray)) throw new TypeError('row must be an array');
  const width = rows[0].length;
  if (rows.some(row => row.length !== width)) throw new TypeError('rows must be rectangular');

  function encodeCell(cell) {
    if (cell !== null && !['string', 'number', 'boolean'].includes(typeof cell)) throw new TypeError('invalid cell');
    if (typeof cell === 'number' && !Number.isFinite(cell)) throw new TypeError('invalid cell');
    const text = cell === null ? '' : String(cell);
    if (!/[,"\r\n]/.test(text)) return text;
    return '"' + text.replace('"', '""') + '"';
  }

  return rows.map(row => row.map(encodeCell).join(',')).join('\n');
}

module.exports = { encodeTable };

