'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['encodeTable']);
const { encodeTable } = api;

assert.strictEqual(encodeTable([]), '');
assert.strictEqual(encodeTable([[]]), '');
assert.strictEqual(encodeTable([[], []]), '\n');
assert.strictEqual(encodeTable([
  ['name', 'count', 'enabled', 'note'],
  ['alpha', 2, true, null],
  ['beta', -0, false, 'plain']
]), 'name,count,enabled,note\nalpha,2,true,\nbeta,0,false,plain');
assert.strictEqual(encodeTable([
  ['a,b', 'say "hello"', 'line1\nline2', 'carriage\rreturn'],
  ['"a"b"', '', 'normal', ',']
]), '"a,b","say ""hello""","line1\nline2","carriage\rreturn"\n"""a""b""",,normal,","');
assert.strictEqual(encodeTable([[1.5, 0, true, false, null]]), '1.5,0,true,false,');

const rows = [['a,b', 'x"y"z'], [null, 4]];
const snapshot = JSON.stringify(rows);
encodeTable(rows);
assert.strictEqual(JSON.stringify(rows), snapshot);

for (const malformed of [
  null,
  {},
  [1],
  [[1], [2, 3]],
  [[undefined]],
  [[{}]],
  [[[]]],
  [[Symbol('x')]],
  [[NaN]],
  [[Infinity]],
  [[-Infinity]]
]) assert.throws(() => encodeTable(malformed), TypeError);

